import { Fragment, useEffect } from "react";
import "./App.css";
import Stopwatch from "./Stopwatch";
import React from "react";

function App() {
  const genders = {
    m: { display: "Homme", time: 0 },
    f: { display: "Femme", time: 0 },
    nb: { display: "Non-Binaire", time: 0 },
  };
  const [time, setTime] = useState(0);
  const [running, setRunning] = useState(false);
  useEffect(() => {
    let interval;
    if (running) {
      interval = setInterval(() => {
        setTime((prevTime) => prevTime + 10);
        (prevTime) => prevTime + 10;
      }, 10);
    } else if (!running) {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [running]);
  return (
    <div className="App">
      {Object.keys(genders).map((gender) => (
        <Fragment>
          <Stopwatch
            display={genders[gender].display}
            key={gender}
            time={genders[gender].time}
          />
          <button>Start {genders[gender]}</button>
        </Fragment>
      ))}
    </div>
  );
}

export default App;
